class Conflict(Exception):
    """Someone else changed the row since you read it."""


class AccountStore:
    """Rows with a version number, like a table with an optimistic-locking column."""

    def __init__(self, balances):
        self._rows = {account: {"balance": balance, "version": 0} for account, balance in balances.items()}

    def read(self, account_id):
        row = self._rows[account_id]
        return row["balance"], row["version"]

    def write(self, account_id, balance, expected_version):
        row = self._rows[account_id]
        row["balance"] = balance
        row["version"] += 1

