TAX_BP = 825  # basis points: 8.25%
FREE_SHIPPING_FROM = 5000  # cents
SHIPPING = 599


class Line:
    def __init__(self, name, unit_cents, qty):
        self.name = name
        self.unit_cents = unit_cents
        self.qty = qty


def subtotal(lines):
    return sum(l.unit_cents * l.qty for l in lines)


def discount(sub, percent):
    return sub * percent // 100


def tax(amount_cents):
    return amount_cents * TAX_BP // 10000


def shipping(sub):
    return 0 if sub > FREE_SHIPPING_FROM else SHIPPING


def total(lines, percent_off=0):
    sub = subtotal(lines)
    taxable = sub - discount(sub, percent_off)
    return sub - discount(sub, percent_off) + tax(sub) + shipping(sub)

