files.inventory.py:
class OutOfStock(Exception):
    pass


class Inventory:
    def __init__(self, stock):
        self._stock = dict(stock)

    def available(self, sku):
        return self._stock.get(sku, 0)

    def reserve(self, sku, quantity):
        """Takes stock for an order; raises OutOfStock if there is not enough."""
        if self.available(sku) < quantity:
            raise OutOfStock(sku)
        self._stock[sku] -= quantity

    def release(self, sku, quantity):
        self._stock[sku] = self.available(sku) + quantity

files.payments.py:
from sched import yield_control


class PaymentDeclined(Exception):
    pass


class FakePayments:
    """Charging takes a moment (it yields), like a real call to the card network."""

    def __init__(self, declined=()):
        self.declined = set(declined)
        self.charged = []

    async def charge(self, user, cents):
        await yield_control()
        if user in self.declined:
            raise PaymentDeclined(user)
        self.charged.append((user, cents))

