class Customer:
    """A person we email. Two customers are the same person if their emails match, ignoring case."""

    def __init__(self, email, name=""):
        self.email = email
        self.name = name

    def __eq__(self, other):
        return isinstance(other, Customer) and self.email.lower() == other.email.lower()

    def __hash__(self):
        return hash(self.email)

    def __repr__(self):
        return "Customer(%r)" % self.email

