import os


class FileStore:
    """Files users uploaded. Everything served must come from inside root."""

    def __init__(self, root):
        self.root = os.path.realpath(root)

    def path_for(self, name):
        # Resolve the final path first ("..", absolute names, symlinks), then check where it landed.
        # os.path.join drops root entirely when name is absolute.
        path = os.path.realpath(os.path.join(self.root, name))
        if os.path.commonpath([path, self.root]) != self.root:
            raise PermissionError("%r is outside the upload directory" % name)
        return path

    def read(self, name):
        with open(self.path_for(name), "rb") as f:
            return f.read()

