class EventBus:
    """Delivers each published event to every handler subscribed to its topic, and remembers what it published."""

    handlers = {}
    published = []

    def subscribe(self, topic, handler):
        self.handlers.setdefault(topic, []).append(handler)

    def unsubscribe(self, topic, handler):
        if handler in self.handlers.get(topic, []):
            self.handlers[topic].remove(handler)

    def publish(self, topic, payload):
        self.published.append((topic, payload))
        delivered = 0
        for handler in list(self.handlers.get(topic, [])):
            handler(payload)
            delivered += 1
        return delivered

    def replay(self, topic):
        """Everything this bus has published on a topic, oldest first."""
        return [payload for t, payload in self.published if t == topic]

