from money import format_money

# Sales tax for the store's state. Accountants round tax half up, to the cent.
TAX_RATE = "0.0875"
CENT = Decimal("0.01")


class Invoice:
    def __init__(self):
        self.lines = []

    def add(self, description, unit_price, qty=1):
        """unit_price is a string in dollars and cents, e.g. "19.99"."""
        # Decimal keeps cents exact; a float cannot hold most of them (0.10 is really 0.1000000000000000055...).
        self.lines.append((description, Decimal(unit_price), qty))

    def subtotal(self):
        return sum((price * qty for _, price, qty in self.lines), Decimal("0"))

    def tax(self):
        return (self.subtotal() * Decimal(TAX_RATE)).quantize(CENT, rounding=ROUND_HALF_UP)

    def total(self):
        return self.subtotal() + self.tax()

    def summary(self):
        return {
            "subtotal": format_money(self.subtotal()),
            "tax": format_money(self.tax()),
            "total": format_money(self.total()),
        }

