class TumblingCounter:
    """Counts events per key in fixed windows of `size` seconds, by when the events HAPPENED."""

    def __init__(self, clock, size, allowed_lateness=0):
        self.clock = clock
        self.size = size
        self.allowed_lateness = allowed_lateness
        self.counts = {}  # window start -> {key: count}
        self.max_ts = None
        self.dropped = 0

    def add(self, event):
        """Counts the event unless it is too late. Returns whether it was counted."""
        if self.max_ts is None or event.ts > self.max_ts:
            self.max_ts = event.ts
        if event.ts < self.max_ts - self.allowed_lateness:
            self.dropped += 1
            return False
        start = (int(self.clock.now()) // self.size) * self.size
        bucket = self.counts.setdefault(start, {})
        bucket[event.key] = bucket.get(event.key, 0) + 1
        return True

