import re

_TOKEN = re.compile(r"[a-z0-9]+")


def tokens(text):
    return _TOKEN.findall(text.lower())


class KeywordIndex:
    """Ranks chunks by how many of the query's words they contain."""

    def __init__(self):
        self._chunks = []

    def add(self, chunks):
        self._chunks.extend(chunks)

    def search(self, query, k=3):
        wanted = set(tokens(query))
        scored = []
        for chunk in self._chunks:
            score = len(wanted & set(tokens(chunk.text)))
            if score:
                scored.append((score, chunk))
        scored.sort(key=lambda pair: (-pair[0], pair[1].doc_id, pair[1].start))
        return [chunk for _, chunk in scored[:k]]

