@dataclass(frozen=True)
class Citation:
    doc_id: str
    start: int
    end: int


def cite(chunk, quote):
    """Where, in the original document, the quote can be found."""
    offset = chunk.text.find(quote)
    if offset < 0:
        raise ValueError("quote is not in the chunk")
    start = chunk.start + offset
    return Citation(chunk.doc_id, start, start + len(quote))

