class TTLCache:
    """Remembers values for `ttl` seconds."""

    def __init__(self, clock, ttl):
        self.clock = clock
        self.ttl = ttl
        self._data = {}  # key -> (value, expires_at)

    def set(self, key, value):
        self._data[key] = (value, self.clock.now() + self.ttl)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, expires_at = entry
        if self.clock.now() >= expires_at:
            del self._data[key]
            return default
        return value

    def get_or_load(self, key, loader):
        """The cached value, or loader(key) if there is none (or it expired); the result is cached."""
        value = self.get(key)
        if value:
            return value
        value = loader(key)
        self.set(key, value)
        return value

