import re


class Router:
    def __init__(self):
        self.routes = []

    def add(self, pattern, handler):
        regex = re.sub(r"<(\w+)>", r"(?P<\1>.+)", pattern)
        self.routes.append((re.compile("^" + regex + "$"), handler))

    def match(self, path):
        for regex, handler in self.routes:
            m = regex.match(path)
            if m:
                return handler, m.groupdict()
        return None

